  'abs(-(1 < 2))', '1 // 0.1', '1 % 0.1', '-1 // 0.1', '5.5 // -2', '5.5 % -2', '0 // -3',
  '0 % -3', '-6 % 3', '7.5 % 2.5', '1.5e-3 * 2', '.5 + 5.', '10 / 4', '-10 // 3 * 3 + -10 % 3',
  'min(3, 1, 2)', 'max(-1, -5)', 'abs(-2.5)', '2 * 3 + 4 ** 0.5 - 1 / 8', '1e400 - 1e400 == 0',
