import json, sys, math
out = []
for f in json.load(sys.stdin):
    v = eval(f, {'__builtins__': {}, 'min': min, 'max': max, 'abs': abs})
    out.append(['bool', v] if isinstance(v, bool) else ['num', repr(float(v))])
print(json.dumps(out))
`], { input: JSON.stringify(formulas) }).toString();

