JSON.parse(py).forEach(([kind, expected], index) => {
  const actual = evaluate(formulas[index]);
  const ok = kind === 'bool' ? actual === expected
    : typeof actual === 'number' && (expected === 'nan' ? Number.isNaN(actual)
      : actual === Number(expected.replace('inf', 'Infinity')));
  if (!ok) { failures += 1; console.log('MISMATCH', formulas[index], actual, expected); }
